import java.lang

log = system.util.getLogger('kanoa_cmms')
log.info('Calling importProcedures()')

errorLog = []

# round-trip through JSON to normalize Java/PyDictionary types to plain python dict/list
data = system.util.jsonDecode(system.util.jsonEncode(data))

records = data.get('procedures', []) if data else []

if not records: return {'passed': False, 'message': 'No procedures to import', 'errorLog': errorLog}

def toInt(value):
	if value is None: return None
	try: return int(value)
	except: return None

# index the exported dataType/engUnit dumps by their old id, and cache
# old-id -> resolved-new-id lookups as they're worked out below
dataTypeRows = data.get('dataTypes', []) if data else []
engUnitRows = data.get('engUnits', []) if data else []
pickListRows = data.get('pickLists', []) if data else []

dataTypeById = {}
for row in dataTypeRows:
	rowId = toInt(row.get('dataTypeId'))
	if rowId is not None: dataTypeById[rowId] = row

engUnitById = {}
for row in engUnitRows:
	rowId = toInt(row.get('engUnitId'))
	if rowId is not None: engUnitById[rowId] = row

pickListById = {}
for row in pickListRows:
	rowId = toInt(row.get('pickListId'))
	if rowId is not None: pickListById[rowId] = row

resolvedDataTypeIds = {}
resolvedEngUnitIds = {}
resolvedPickListIds = {}

def resolveDataTypeId(oldId):
	oldId = toInt(oldId)
	if oldId is None: return None
	if oldId in resolvedDataTypeIds: return resolvedDataTypeIds[oldId]

	oldRow = dataTypeById.get(oldId)
	name = oldRow.get('dataTypeName') if oldRow else None
	if not name: return None

	newId = system.kanoa.utilities.getFieldValue('dataTypeId', system.kanoa.quality.config.getDataTypes({'dataTypeName': name}))
	if newId is None:
		newDataTypeInfo = {
			'dataTypeName': name,
			'enabled': oldRow.get('enabled', True),
			'isNumeric': oldRow.get('isNumeric', False),
			'pickListEnabled': oldRow.get('pickListEnabled', False)
		}
		newId = system.kanoa.quality.config.addDataType(newDataTypeInfo, userId)

	resolvedDataTypeIds[oldId] = newId
	return newId

def resolveEngUnitId(oldId):
	oldId = toInt(oldId)
	if oldId is None: return None
	if oldId in resolvedEngUnitIds: return resolvedEngUnitIds[oldId]

	oldRow = engUnitById.get(oldId)
	name = oldRow.get('engUnitName') if oldRow else None
	if not name: return None

	newId = system.kanoa.utilities.getFieldValue('engUnitId', system.kanoa.quality.config.getUnits({'engUnitName': name}))
	if newId is None:
		newUnitInfo = {'engUnitName': name, 'enabled': oldRow.get('enabled', True)}
		newId, msg = system.kanoa.quality.config.addUnit(newUnitInfo, userId)
		if msg: return None

	resolvedEngUnitIds[oldId] = newId
	return newId

def resolvePickListId(oldId):
	oldId = toInt(oldId)
	if oldId is None: return None
	if oldId in resolvedPickListIds: return resolvedPickListIds[oldId]

	oldRow = pickListById.get(oldId)
	name = oldRow.get('pickListName') if oldRow else None
	if not name: return None

	newId = system.kanoa.utilities.getFieldValue('pickListId', system.kanoa.quality.config.getPickList({'pickListName': name}))
	if newId is None:
		newPickListInfo = {
			'pickListName': name,
			'description': oldRow.get('description'),
			'enabled': oldRow.get('enabled', True),
			'isNumeric': oldRow.get('isNumeric', False),
			'dataTypeId': resolveDataTypeId(oldRow.get('dataTypeId')),
			'example': oldRow.get('example')
		}
		newId, msg = system.kanoa.quality.config.addPickList(newPickListInfo, userId)
		if msg: return None

	resolvedPickListIds[oldId] = newId
	return newId

def remapConfig(configStr):
	# rewrites dataTypeId/engUnitId/pickListInfo.pickListId to the target system's equivalent
	# record, resolved by name (created if missing)
	if not configStr: return configStr
	config = system.util.jsonDecode(configStr)
	if config is None: return configStr
	if 'dataTypeId' in config: config['dataTypeId'] = resolveDataTypeId(config.get('dataTypeId'))
	if 'engUnitId' in config: config['engUnitId'] = resolveEngUnitId(config.get('engUnitId'))
	pickListInfo = config.get('pickListInfo')
	if pickListInfo is not None and 'pickListId' in pickListInfo: pickListInfo['pickListId'] = resolvePickListId(pickListInfo.get('pickListId'))
	return system.util.jsonEncode(config)

categoryIdByPath = system.kanoa.utilities.convertDatasetToDict(system.kanoa.cmms.getProcedureCategory({}), 'procedureCategoryPath', 'procedureCategoryId')

importedCount = 0

for record in records:
	procedureInfo = record['procedure'] if 'procedure' in record else None
	steps = record['steps'] if 'steps' in record else []

	if procedureInfo is None:
		errorLog.append('A record had no procedure info and was skipped.')
		continue

	# resolve/create the procedure category chain from procedureCategoryPath
	categoryPath = procedureInfo.get('procedureCategoryPath')
	procedureCategoryId = None
	categoryFailed = False

	if categoryPath:
		pathSections = [section.strip() for section in categoryPath.split('\\')]
		builtPath = None
		for section in pathSections:
			builtPath = '%s\\%s'%(builtPath, section) if builtPath else section
			if builtPath in categoryIdByPath:
				procedureCategoryId = categoryIdByPath[builtPath]
				continue
			newCategoryInfo = {'procedureCategoryName': section, 'parentId': procedureCategoryId, 'enabled': True}
			procedureCategoryId, msg = system.kanoa.cmms.addProcedureCategory(newCategoryInfo, userId)
			if msg:
				errorLog.append('Unable to create procedure category "%s". %s'%(builtPath, msg))
				categoryFailed = True
				break
			categoryIdByPath[builtPath] = procedureCategoryId

	if categoryFailed:
		errorLog.append('Procedure "%s" was not imported - could not resolve its category.'%procedureInfo.get('procedureName'))
		continue

	# de-dupe on name collision within the same category
	procedureName = procedureInfo.get('procedureName')
	existingProcedures = system.kanoa.utilities.convertDatasetToJSON(system.kanoa.cmms.getProcedures({'procedureName': procedureName}))
	existingProcedureId = None
	for existingProcedure in existingProcedures:
		if existingProcedure['procedureCategoryId'] == procedureCategoryId:
			existingProcedureId = existingProcedure['procedureId']
			break
	if existingProcedureId is not None:
		procedureName = '%s (%s)'%(procedureName, system.date.format(system.date.now(), 'yyyy-MM-dd HH.mm.ss'))

	newProcedureInfo = {
		'procedureName': procedureName,
		'procedureDescription': procedureInfo.get('procedureDescription'),
		'procedureCategoryId': procedureCategoryId,
		'enabled': procedureInfo.get('enabled', True)
	}

	procedureId, msg = system.kanoa.cmms.addProcedure(newProcedureInfo, userId)
	if msg:
		errorLog.append('Procedure "%s" could not be imported. %s'%(procedureName, msg))
		continue

	for step in sorted(steps, key=lambda x: x['sortOrder']):
		checks = step['checks'] if 'checks' in step else []

		try:
			newStepInfo = {
				'procedureId': procedureId,
				'stepName': step['stepName'],
				'stepDescription': step['stepDescription'],
				'estimatedMinutes': step['estimatedMinutes'],
				'sortOrder': step['sortOrder'],
				'enabled': step['enabled'],
				'required': step['required'],
				'stepConfig': remapConfig(step['stepConfig'])
			}
		except java.lang.Exception, e:
			errorLog.append('Step "%s" for procedure "%s" could not resolve its data type/engineering unit references. %s'%(step['stepName'], procedureName, e.cause if e.cause else str(e)))
			continue
		except Exception, e:
			errorLog.append('Step "%s" for procedure "%s" could not resolve its data type/engineering unit references. %s'%(step['stepName'], procedureName, str(e)))
			continue

		procedureStepId, msg = system.kanoa.cmms.addProcedureStep(newStepInfo, userId)
		if msg:
			errorLog.append('Step "%s" for procedure "%s" could not be imported. %s'%(step['stepName'], procedureName, msg))
			continue

		for check in sorted(checks, key=lambda x: x['sortOrder']):
			try:
				newCheckInfo = {
					'procedureStepId': procedureStepId,
					'checkName': check['checkName'],
					'checkDescription': check['checkDescription'],
					'checkConfig': remapConfig(check['checkConfig']),
					'enabled': check['enabled'],
					'required': check['required'],
					'sortOrder': check['sortOrder']
				}
			except java.lang.Exception, e:
				errorLog.append('Check "%s" for step "%s" could not resolve its data type/engineering unit references. %s'%(check['checkName'], step['stepName'], e.cause if e.cause else str(e)))
				continue
			except Exception, e:
				errorLog.append('Check "%s" for step "%s" could not resolve its data type/engineering unit references. %s'%(check['checkName'], step['stepName'], str(e)))
				continue

			procedureStepCheckId, msg = system.kanoa.cmms.addProcedureStepCheck(newCheckInfo, userId)
			if msg: errorLog.append('Check "%s" for step "%s" could not be imported. %s'%(check['checkName'], step['stepName'], msg))

	importedCount += 1

if importedCount == 0: return {'passed': False, 'message': 'No procedures were imported', 'errorLog': errorLog}

return {'passed': True, 'message': '%s procedure(s) imported'%importedCount, 'errorLog': errorLog}

